func TestSplitDocExamples(t *testing.T) {
	// Examples from ratatui 0.29's Layout::split / split_with_spacers docs.
	got := Split(NewRect(2, 2, 10, 10), Vertical, Length(5), Min(0))
	want := []Rect{NewRect(2, 2, 10, 5), NewRect(2, 7, 10, 5)}
	if fmt.Sprint(got) != fmt.Sprint(want) {
		t.Errorf("vertical: got %v want %v", got, want)
	}
	got = Split(NewRect(0, 0, 9, 2), Horizontal, Ratio(1, 3), Ratio(2, 3))
	want = []Rect{NewRect(0, 0, 3, 2), NewRect(3, 0, 6, 2)}
	if fmt.Sprint(got) != fmt.Sprint(want) {
		t.Errorf("ratio: got %v want %v", got, want)
	}
	segs, spacers := Layout{Direction: Horizontal, Spacing: 1, Constraints: []Constraint{Ratio(1, 3), Ratio(2, 3)}}.
		SplitWithSpacers(NewRect(0, 0, 10, 2))
	if want := []Rect{NewRect(0, 0, 3, 2), NewRect(4, 0, 6, 2)}; fmt.Sprint(segs) != fmt.Sprint(want) {
		t.Errorf("spacing segments: got %v want %v", segs, want)
	}
	if want := []Rect{NewRect(0, 0, 0, 2), NewRect(3, 0, 1, 2), NewRect(10, 0, 0, 2)}; fmt.Sprint(spacers) != fmt.Sprint(want) {
		t.Errorf("spacing spacers: got %v want %v", spacers, want)
	}
}

func TestSplitTerminates(t *testing.T) {
	// With an unlucky HashMap seed the Rust solver was observed to cycle forever on this
	// input; the deterministic pivot order used here must terminate.
	l := Layout{Direction: Horizontal, Spacing: 4, HorizontalMargin: 3, VerticalMargin: 3, Constraints: []Constraint{Fill(3)}}
	segs, spacers := l.SplitWithSpacers(NewRect(17, 21, 234, 46))
	if got, want := fmtRects(segs)+" / "+fmtRects(spacers), "20,24,228,40 / 20,24,0,40 248,24,0,40"; got != want {
		t.Errorf("got %s want %s", got, want)
	}
}

func TestCassowaryDocExample(t *testing.T) {
	// The example from the cassowary crate's top-level documentation.
	ww := cassowary.NewVariable()
	b1l, b1r := cassowary.NewVariable(), cassowary.NewVariable()
	b2l, b2r := cassowary.NewVariable(), cassowary.NewVariable()
	s := cassowary.NewSolver()
	c := cassowary.Const
	err := s.AddConstraints(
		cassowary.Ge(ww.Expr(), cassowary.Required, c(0)),
		cassowary.Eq(b1l.Expr(), cassowary.Required, c(0)),
		cassowary.Eq(b2r.Expr(), cassowary.Required, ww.Expr()),
		cassowary.Ge(b2l.Expr(), cassowary.Required, b1r.Expr()),
		cassowary.Le(b1l.Expr(), cassowary.Required, b1r.Expr()),
		cassowary.Le(b2l.Expr(), cassowary.Required, b2r.Expr()),
		cassowary.Eq(b1r.Sub(b1l), cassowary.Weak, c(50)),
		cassowary.Eq(b2r.Sub(b2l), cassowary.Weak, c(100)),
	)
	if err != nil {
		t.Fatal(err)
	}
	if err := s.AddEditVariable(ww, cassowary.Strong); err != nil {
		t.Fatal(err)
	}
	if err := s.SuggestValue(ww, 300); err != nil {
		t.Fatal(err)
	}
	s.FetchChanges()
	check := func(v cassowary.Variable, want float64) {
		t.Helper()
		if got := s.GetValue(v); math.Abs(got-want) > 1e-9 {
			t.Errorf("got %v want %v", got, want)
		}
	}
	check(ww, 300)
	check(b1l, 0)
	check(b1r, 50)
	check(b2l, 200)
	check(b2r, 300)
	if err := s.SuggestValue(ww, 75); err != nil {
		t.Fatal(err)
	}
	if err := s.AddConstraint(cassowary.Eq(b1r.Sub(b1l).Div(50), cassowary.Medium, b2r.Sub(b2l).Div(100))); err != nil {
		t.Fatal(err)
	}
	check(ww, 75)
	check(b1r, 25)
	check(b2l, 25)
	check(b2r, 75)
	if err := s.AddEditVariable(ww, cassowary.Strong); err != cassowary.ErrDuplicateEditVariable {
		t.Errorf("duplicate edit variable: got %v", err)
	}
	if got := cassowary.CreateStrength(1, 2, 3, 2); got != 2_004_006 {
		t.Errorf("CreateStrength = %v", got)
	}
}

// parseLayoutCase parses "DIR FLEX SPACING HMARGIN VMARGIN X Y W H : CONSTRAINTS".
// DIR is V/H; FLEX is G(legacy) S(start) E(end) C(center) B(space-between)
// A(space-around); constraints are L<n> M<n> X<n>(max) P<n> F<n> R<n>/<d>.
func parseLayoutCase(t *testing.T, s string) (Layout, Rect) {
	head, cs, _ := strings.Cut(s, ":")
	h := strings.Fields(head)
	atoi := func(s string) int {
		n, err := strconv.Atoi(s)
		if err != nil {
			t.Fatalf("bad case %q: %v", s, err)
		}
		return n
	}
	var l Layout
	if h[0] == "H" {
		l.Direction = Horizontal
	}
	l.Flex = map[string]Flex{"G": FlexLegacy, "S": FlexStart, "E": FlexEnd, "C": FlexCenter, "B": FlexSpaceBetween, "A": FlexSpaceAround}[h[1]]
	l.Spacing = atoi(h[2])
	l.HorizontalMargin = atoi(h[3])
	l.VerticalMargin = atoi(h[4])
	area := NewRect(atoi(h[5]), atoi(h[6]), atoi(h[7]), atoi(h[8]))
	for _, c := range strings.Fields(cs) {
		k, v := c[:1], c[1:]
		switch k {
		case "L":
			l.Constraints = append(l.Constraints, Length(atoi(v)))
		case "M":
			l.Constraints = append(l.Constraints, Min(atoi(v)))
		case "X":
			l.Constraints = append(l.Constraints, Max(atoi(v)))
		case "P":
			l.Constraints = append(l.Constraints, Percentage(atoi(v)))
		case "F":
			l.Constraints = append(l.Constraints, Fill(atoi(v)))
		case "R":
			a, b, _ := strings.Cut(v, "/")
			l.Constraints = append(l.Constraints, Ratio(atoi(a), atoi(b)))
		default:
			t.Fatalf("bad constraint %q", c)
		}
	}
	return l, area
}

func fmtRects(rs []Rect) string {
	parts := make([]string, len(rs))
	for i, r := range rs {
		parts[i] = fmt.Sprintf("%d,%d,%d,%d", r.X, r.Y, r.Width, r.Height)
	}
	return strings.Join(parts, " ")
}

// TestSplitMatchesRatatui compares against output recorded from ratatui 0.29.0
// (Layout::default().direction(..).flex(..).spacing(..).margin(..).constraints(..)
// .split_with_spacers(area)). Each line is "CASE = SEGMENTS[ / SPACERS]" with
// rects written as x,y,w,h. Only inputs for which ratatui itself is
// deterministic across runs are included (ratatui's solver iterates
// randomly-seeded HashMaps, so a few degenerate inputs vary between runs).
func TestSplitMatchesRatatui(t *testing.T) {
	n := 0
	for _, line := range strings.Split(strings.TrimSpace(ratatuiLayoutCorpus), "\n") {
		k, want, _ := strings.Cut(line, " = ")
		l, area := parseLayoutCase(t, k)
		segs, spacers := l.SplitWithSpacers(area)
		got := fmtRects(segs)
		if strings.Contains(want, " / ") {
			got += " / " + fmtRects(spacers)
		}
		if got != want {
			t.Errorf("%s\n got  %s\n want %s", k, got, want)
		}
		n++
	}
	if n < 2000 {
		t.Fatalf("corpus too small: %d", n)
	}
}

func TestSplitConvenience(t *testing.T) {
	area := NewRect(0, 0, 80, 24)
	got := Split(area, Vertical, Length(4), Min(10), Length(3))
	l := Layout{Direction: Vertical, Constraints: []Constraint{Length(4), Min(10), Length(3)}}
	if fmt.Sprint(got) != fmt.Sprint(l.Split(area)) {
		t.Fatalf("Split and Layout.Split disagree")
	}
	if want := "0,0,80,4 0,4,80,17 0,21,80,3"; fmtRects(got) != want {
		t.Errorf("got %s want %s", fmtRects(got), want)
	}
}

